import { describe, expect, it } from 'vitest';
import { emailError, usernameError } from './username';

// Story 14-S1 — the sign-in form's username and email rules.
//
// Each function takes the field's raw value and returns the message to show,
// or null when the value is acceptable once trimmed. The form and the auth
// hook share them; the hook ignores a username its rule refuses. The browser
// cases are in e2e/sign-in.spec.ts.
// Do not edit this file to match an implementation.

const BLANK_USERNAME = 'Oops! You need to add a username.';
const LONG_USERNAME = 'Oops! Use 80 characters or fewer.';
const BLANK_EMAIL = 'Oops! You need to add an email address.';
const BAD_EMAIL = "Oops! That doesn't look like an email address.";

describe('14-S1-1 usernameError', () => {
  it('accepts an ordinary username', () => {
    expect(usernameError('Ada')).toBeNull();
    expect(usernameError('山田 🦖 & Co.')).toBeNull();
  });

  it('refuses a blank or whitespace-only username', () => {
    expect(usernameError('')).toBe(BLANK_USERNAME);
    expect(usernameError('   ')).toBe(BLANK_USERNAME);
    expect(usernameError(' \t\n ')).toBe(BLANK_USERNAME);
  });

  it('refuses a value that is not a string as blank', () => {
    expect(usernameError(undefined)).toBe(BLANK_USERNAME);
    expect(usernameError(null)).toBe(BLANK_USERNAME);
    expect(usernameError(42)).toBe(BLANK_USERNAME);
  });

  it('counts code points of the trimmed value: 80 passes, 81 does not', () => {
    expect(usernameError('a'.repeat(80))).toBeNull();
    expect(usernameError('a'.repeat(81))).toBe(LONG_USERNAME);
    // Each astral character is two UTF-16 units but one code point.
    expect(usernameError('🦖'.repeat(80))).toBeNull();
    expect(usernameError('🦖'.repeat(81))).toBe(LONG_USERNAME);
  });

  it('measures the length after trimming', () => {
    expect(usernameError(`  ${'a'.repeat(80)}  `)).toBeNull();
  });
});

describe('14-S1-2 emailError', () => {
  it('accepts a well-formed address, trimmed', () => {
    expect(emailError('ada@example.com')).toBeNull();
    expect(emailError('a.b+c@mail.example.co.uk')).toBeNull();
    expect(emailError('  ada@example.com  ')).toBeNull();
  });

  it('refuses a blank or whitespace-only address', () => {
    expect(emailError('')).toBe(BLANK_EMAIL);
    expect(emailError('   ')).toBe(BLANK_EMAIL);
    expect(emailError(undefined)).toBe(BLANK_EMAIL);
  });

  it('refuses a malformed address', () => {
    for (const value of [
      'ada',
      'ada@',
      '@example.com',
      'ada@example',
      'ada@@example.com',
      'ada@ex@ample.com',
      'ada lovelace@example.com',
      'ada@exa mple.com',
      'ada@.example',
      'ada@example.',
      'ada@.',
    ]) {
      expect(emailError(value), value).toBe(BAD_EMAIL);
    }
  });
});
